    """A tuple-returning block (gpt-oss-style) -> must decline."""

    def forward(self, hidden_states):
        x = hidden_states.reshape(-1, hidden_states.shape[-1])
        _, weights, index = self.gate(x)
        return self.experts(x, index, weights), index

